def can_be_valid_by_inversion(bracket_sequence):
    stack = []
    open_brackets = []

    for i, char in enumerate(bracket_sequence):
        if char == '(':
            stack.append(i)
            open_brackets.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                open_brackets.append(i)

    if len(stack) % 2 != 0:
        return "impossible"

    if not stack:
        return "possible"

    first_unmatched = stack[0]
    last_unmatched = stack[-1]

    # Check if inverting the segment [first_unmatched, last_unmatched] makes the sequence valid
    if first_unmatched > 0 and bracket_sequence[first_unmatched - 1] == '(':
        return "possible"

    if last_unmatched < len(bracket_sequence) - 1 and bracket_sequence[last_unmatched + 1] == ')':
        return "possible"

    # Check if inverting any single unmatched parenthesis makes the sequence valid
    for pos in open_brackets:
        temp_seq = list(bracket_sequence)
        temp_seq[pos] = ')' if temp_seq[pos] == '(' else '('
        if is_valid(temp_seq):
            return "possible"

    return "impossible"

