    stack = []
    imbalance_positions = []

    # First pass to find imbalances
    for i, char in enumerate(bracket_sequence):
        if char == '(':
            stack.append(i)
        elif char == ')' and stack:
            stack.pop()
        else:
            imbalance_positions.append(i)

    # If already balanced, no need for inversion
    if not stack and not imbalance_positions:
        return "possible"

    # If there's more than one imbalance, cannot fix with one inversion
    if len(imbalance_positions) > 2:
        return "impossible"

    # Try inverting segments around identified imbalances
    if len(imbalance_positions) == 1:
        pos = imbalance_positions[0]
        if pos == 0 or pos == len(bracket_sequence) - 1:
            return "possible"
        if (pos > 0 and bracket_sequence[pos - 1] == '(') or (pos < len(bracket_sequence) - 1 and bracket_sequence[pos + 1] == ')'):
            return "possible"

    if len(imbalance_positions) == 2:
        start, end = sorted(imbalance_positions)
        if start == 0 and end == len(bracket_sequence) - 1:
            return "possible"
        if (start > 0 and bracket_sequence[start - 1] == '(') or (end < len(bracket_sequence) - 1 and bracket_sequence[end + 1] == ')'):
            return "possible"

    return "impossible"

