        elif char == ')' and stack:
            stack.pop()
        else:
            stack.append(i)

    if len(stack) <= 2:
        return "possible"

    # Try to find a single inversion that fixes the sequence
    for i in range(len(stack) - 1):
        start = stack[i]
        end = stack[i + 1]
        inverted_sequence = list(bracket_sequence)
        for j in range(start, end + 1):
            inverted_sequence[j] = '(' if inverted_sequence[j] == ')' else ')'

        temp_stack = []
        valid = True
        for char in inverted_sequence:
            if char == '(':
                temp_stack.append(char)
            elif char == ')' and temp_stack:
                temp_stack.pop()
            else:
                valid = False
                break

        if valid and not temp_stack:
            return "possible"

    return "impossible"

